+package main
+
+import (
+	"fmt"
+	"github.com/antonmedv/fx/internal/jsonx"
+)
+
+func main() {
+	// Test JSON with various escape sequences
+	testJSON := []byte(`{"test": "Hello\nWorld\t!", "unicode": "Unicode: \u0041", "quotes": "He said \"Hello World\"", "backslash": "Backslash: \\", "mixed": "Mixed: \n\t\"\\\\"}`)
+
+	fmt.Println("Original JSON:")
+	fmt.Println(string(testJSON))
+
+	// Parse the JSON
+	node, err := jsonx.Parse(testJSON)
+	if err != nil {
+		fmt.Printf("Error parsing JSON: %v\n", err)
+		return
+	}
+
+	fmt.Println("\nParsed values:")
+	current := node
+	for current != nil {
+		if current.Key != "" && current.Value != "" {
+			fmt.Printf("Key: %s, Value: %s\n", current.Key, current.Value)
+		}
+		current = current.Next
+	}
+}
